CREATE TABLE users (
    id   INTEGER PRIMARY KEY,   -- первичный ключ: уникален у каждой строки
    name TEXT NOT NULL
);

CREATE TABLE orders (
    id      INTEGER PRIMARY KEY,
    user_id INTEGER NOT NULL,   -- внешний ключ: ссылка на users.id
    amount  INTEGER NOT NULL,   -- сумма в копейках: деньги не хранят во float
    FOREIGN KEY (user_id) REFERENCES users (id)
);

-- «Дай имена всех пользователей»
SELECT name FROM users;

-- «Дай заказы дороже 1000 копеек»
SELECT id, amount FROM orders WHERE amount > 1000;
